/*
 * Compatibility stand-in, not GSAP. Pages generated by earlier versions of
 * nr_landingpage load this file and run scripts stored in the page that use
 * GSAP. GSAP is no longer shipped (see Documentation/Usage).
 *
 * The contract is deliberately small:
 *
 * - The animation script the extension generated keeps its content. Its
 *   typewriter empties a heading and then calls gsap.to(el, {text: ...}), so
 *   the stand-in writes text, from to(), set() and the last object of
 *   fromTo(), into elements that have no child nodes at that moment. That is the only
 *   change it makes to a page: it never writes over text, and never changes
 *   opacity, visibility or any other style.
 * - Common GSAP 3 code runs without an error, as far as it can: every
 *   global the GSAP 3 files defined (gsap, ScrollTrigger, Observer,
 *   TextPlugin, TweenMax, TimelineMax, the ease objects, ...) is an inert
 *   value; reading, assigning, calling, constructing or iterating it gives
 *   another inert value, awaiting one settles in a macrotask, and numbers
 *   read from one are 1. This is not a guarantee: a script that waits for a
 *   GSAP value to become false, for example, loops forever.
 * - Nothing else: no animation and no callbacks of the page apart from
 *   promise continuations (`await`, `.then()`). Scripts that an LLM wrote
 *   in creative mode are not emulated; such pages need to be generated
 *   again.
 *
 * ScrollTrigger.min.js and TextPlugin.min.js only remain for the script tags
 * of those pages.
 */
(function () {
  'use strict';

  // Values that currently must not look thenable: one that a promise is
  // settling with, or whose continuation runs. GSAP clears `then` on the
  // tween concerned in the same two places.
  var settling = typeof WeakSet === 'function' ? new WeakSet() : null;

  // Arrays, NodeLists, HTMLCollections, jQuery objects, `arguments`: as
  // GSAP's own check, an object with a length that is not an element or
  // the window.
  function isList(value) {
    return value !== null && typeof value === 'object' && typeof value.length === 'number'
      && !value.nodeType && value !== window;
  }

  function select(selector) {
    try {
      return Array.prototype.slice.call(document.querySelectorAll(selector));
    } catch (e) {
      return []; // Not a selector, for example a media query.
    }
  }

  // As gsap.utils.toArray(): selectors give their elements, lists are
  // flattened, any other value gives a list with that value.
  function toArray(value, depth) {
    if (typeof value === 'string') {
      return select(value);
    }
    if (isList(value)) {
      var flat = [];
      Array.prototype.forEach.call(value, function (entry) {
        Array.prototype.push.apply(flat, (depth || 0) < 3 ? toArray(entry, (depth || 0) + 1) : [entry]);
      });
      return flat;
    }
    return value ? [value] : [];
  }

  function elements(target) {
    return toArray(target).filter(function (item) { return item && item.nodeType === 1; });
  }

  // The only value the stand-in writes: text, into elements without child
  // nodes at that moment (the extension's typewriter empties them first).
  function show(nodes, vars) {
    if (vars === null || typeof vars !== 'object') {
      return;
    }
    var text = vars.text;
    if (text !== null && typeof text === 'object') {
      text = text.value;
    }
    if (typeof text !== 'string' || text === '') {
      return;
    }
    nodes.forEach(function (element) {
      // No child nodes at all: an element holding only an image or an
      // icon has empty textContent but is not empty.
      if (element.firstChild === null) {
        element.textContent = text;
      }
    });
  }

  // to(), set() and the rest take end values from every object argument,
  // fromTo() from its last one, from() from none: its values are start values.
  function handle(method, args) {
    var nodes = elements(args[0]);
    var objects = [];
    for (var i = 1; i < args.length; i++) {
      if (args[i] !== null && typeof args[i] === 'object') {
        objects.push(args[i]);
      }
    }
    if (method === 'from' || method === 'staggerFrom') {
      objects = [];
    } else if (method === 'fromTo' || method === 'staggerFromTo') {
      objects = objects.slice(-1);
    }
    objects.forEach(function (vars) { show(nodes, vars); });
    return create('');
  }

  function create(method) {
    var proxy = new Proxy(function () {}, {
      get: function (target, property) {
        // A property defined read-only on the target must be returned as it
        // is (a Proxy invariant), for example after Object.defineProperty().
        var own = Object.getOwnPropertyDescriptor(target, property);
        if (own && !own.configurable && !own.writable && 'value' in own) {
          return own.value;
        }
        if (property === 'then') {
          if (settling !== null && settling.has(proxy)) {
            return undefined;
          }
          return function (onFulfilled, onRejected) {
            // A macrotask, so that `while (true) { await tween; }` leaves
            // the page responsive as it does with GSAP.
            return new Promise(function (resolve) {
              setTimeout(function () { guarded(proxy, resolve); }, 0);
            }).then(function (value) {
              return typeof onFulfilled === 'function' ? guarded(value, onFulfilled) : value;
            }, onRejected);
          };
        }
        if (property === 'toArray') {
          return function (value) { return toArray(value); };
        }
        if (property === Symbol.toPrimitive) {
          // Numbers read from the stand-in (duration(), progress(), ...) are
          // 1, so loops that step by them or wait for them to reach 1 end.
          return function () { return 1; };
        }
        return create(typeof property === 'string' ? property : '');
      },
      // The target's name and length are read-only; assigning them must
      // not throw in strict mode.
      set: function () { return true; },
      apply: function (target, self, args) {
        return handle(method, args);
      },
      construct: function (target, args) {
        handle(method, args);
        return create('');
      }
    });
    return proxy;
  }

  function guarded(value, callback) {
    if (settling !== null) {
      settling.add(value);
    }
    try {
      return callback(value);
    } finally {
      if (settling !== null) {
        settling.delete(value);
      }
    }
  }

  [
    'gsap', 'ScrollTrigger', 'Observer', 'TextPlugin', 'CSSPlugin', 'AttrPlugin', 'EndArrayPlugin',
    'ModifiersPlugin', 'RoundPropsPlugin', 'SnapPlugin', 'gsapVersions',
    'TweenLite', 'TweenMax', 'TimelineLite', 'TimelineMax',
    'Back', 'Bounce', 'Circ', 'Cubic', 'Elastic', 'Expo', 'Linear', 'Power0', 'Power1', 'Power2',
    'Power3', 'Power4', 'Quad', 'Quart', 'Quint', 'Sine', 'SteppedEase', 'Strong'
  ].forEach(function (name) {
    // An element with that id is reachable as window[name]; GSAP replaces
    // it, and so does the stand-in.
    var current = window[name];
    if (current === undefined || (current && (current.nodeType === 1 || current instanceof HTMLCollection))) {
      window[name] = create('');
    }
  });
})();
